/** Apply a theme to an element (default: the document root). */
export function setTheme(id, el = document.documentElement) {
  el.dataset.dpTheme = id;
}

/** Pin "light" or "dark", or follow the OS with "system". */
export function setMode(mode, el = document.documentElement) {
  el.dataset.dpMode = mode;
}
